def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    opp_def = 0
    me_def = 0
    for a in opp:
        if a == 'D':
            opp_def += 1
    for a in me:
        if a == 'D':
            me_def += 1
    last_me, last_opp = history[-1]

    # Endgame: defect in final rounds, but only if opponent is not clearly
    # an always-cooperator we can safely exploit all the way.
    if n >= 98:
        return 'D'

    recent = opp[-8:] if n >= 8 else opp
    recent_def = 0
    for a in recent:
        if a == 'D':
            recent_def += 1
    rlen = len(recent)

    # Sustained / heavy defector: match defection, but occasionally probe.
    if rlen >= 4 and recent_def * 2 >= rlen:
        if recent_def == rlen:
            return 'D'
        if last_opp == 'C' and rng.random() < 0.3:
            return 'C'
        return 'D'

    # Repetitive defector over whole match.
    if opp_def >= 6 and opp_def * 2 > n:
        return 'D'

    # After four early defections, TFT-style opponents settle down if we
    # return to C.  The parent recovers slowly here; be more willing to
    # offer C once the recent streak is not all-D.
    if last_opp == 'D':
        # Count current opponent defect streak.
        streak = 0
        i = n - 1
        while i >= 0:
            if opp[i] == 'D':
                streak += 1
                i -= 1
            else:
                break
        # Very long streak: stay defensive.
        if streak >= 4:
            return 'D'
        # Moderate streak: punish once more, then forgive.
        if streak >= 2:
            if rng.random() < 0.3:
                return 'C'
            return 'D'
        # Single defection: forgive with decent probability to reset TFT.
        if rng.random() < 0.4:
            return 'C'
        return 'D'

    # Opponent last cooperated.
    if last_opp == 'C':
        # If we have been defecting a lot recently while opponent is calm,
        # offer cooperation to repair.
        if n >= 6:
            my_recent_def = 0
            for a in me[-6:]:
                if a == 'D':
                    my_recent_def += 1
            if my_recent_def >= 3 and opp_def * 3 < n:
                return 'C'
        return 'C'

    return 'C'
